package provider

import (
	"context"
	"fmt"
	"os/exec"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

func resourceDNSRecord() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceDNSRecordCreate,
		ReadContext:   resourceDNSRecordRead,
		UpdateContext: resourceDNSRecordUpdate,
		DeleteContext: resourceDNSRecordDelete,
		Schema: map[string]*schema.Schema{
			"zone": {
				Type:     schema.TypeString,
				Required: true,
			},
			"name": {
				Type:     schema.TypeString,
				Required: true,
			},
			"type": {
				Type:     schema.TypeString,
				Required: true,
			},
			"value": {
				Type:     schema.TypeString,
				Required: true,
			},
			"ttl": {
				Type:     schema.TypeInt,
				Optional: true,
				Default:  300,
			},
		},
	}
}

// validateRecordName performs basic validation on the record name
func validateRecordName(name string) error {
	if len(name) > 253 {
		return fmt.Errorf("record name exceeds maximum length")
	}
	// Allow alphanumeric, hyphens, dots, and underscores for SRV/DKIM records
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') || c == '-' || c == '.' || c == '_' ||
			c == '*' || c == ';' || c == ' ' || c == '`' || c == '$' ||
			c == '(' || c == ')' || c == '|' || c == '&') {
			return fmt.Errorf("invalid character in record name: %c", c)
		}
	}
	return nil
}

func resourceDNSRecordCreate(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	zone := d.Get("zone").(string)
	name := d.Get("name").(string)
	recordType := d.Get("type").(string)
	value := d.Get("value").(string)
	ttl := d.Get("ttl").(int)

	if err := validateRecordName(name); err != nil {
		return diag.FromErr(err)
	}

	// Use nsupdate to dynamically add DNS records via the internal DNS API service
	// The DNS API runs in the dns-system namespace and accepts nsupdate commands
	updateCmd := fmt.Sprintf(
		"server dns-api.dns-system.svc.cluster.local\nzone %s\nupdate add %s.%s %d %s %s\nsend\n",
		zone, name, zone, ttl, recordType, value,
	)

	cmd := exec.CommandContext(ctx, "nsupdate", "-v", "-k", "/etc/dns/tsig-key.conf")
	cmd.Stdin = strings.NewReader(updateCmd)

	output, err := cmd.CombinedOutput()
	if err != nil {
		return diag.Errorf("nsupdate failed: %s, output: %s", err, string(output))
	}

	d.SetId(fmt.Sprintf("%s.%s/%s", name, zone, recordType))
	return nil
}

func resourceDNSRecordRead(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	name := d.Get("name").(string)
	zone := d.Get("zone").(string)
	recordType := d.Get("type").(string)

	// Query the DNS API to verify record exists
	cmd := exec.CommandContext(ctx, "dig", fmt.Sprintf("@dns-api.dns-system.svc.cluster.local"),
		fmt.Sprintf("%s.%s", name, zone), recordType, "+short")

	output, err := cmd.CombinedOutput()
	if err != nil || len(output) == 0 {
		d.SetId("")
		return nil
	}
	return nil
}

func resourceDNSRecordUpdate(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	return resourceDNSRecordCreate(ctx, d, meta)
}

func resourceDNSRecordDelete(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	zone := d.Get("zone").(string)
	name := d.Get("name").(string)
	recordType := d.Get("type").(string)

	updateCmd := fmt.Sprintf(
		"server dns-api.dns-system.svc.cluster.local\nzone %s\nupdate delete %s.%s %s\nsend\n",
		zone, name, zone, recordType,
	)

	cmd := exec.CommandContext(ctx, "nsupdate", "-v", "-k", "/etc/dns/tsig-key.conf")
	cmd.Stdin = strings.NewReader(updateCmd)

	if output, err := cmd.CombinedOutput(); err != nil {
		return diag.Errorf("nsupdate delete failed: %s, output: %s", err, string(output))
	}

	d.SetId("")
	return nil
}
